mapper.select:
SELECT DISTINCT MENU_CODE
FROM perm_feature_menu
WHERE MENU_SCOPE = #{menuScope}
  AND TENANT_ID = #{tenantId}

SELECT COUNT(1)
FROM perm_feature_menu
WHERE MENU_SCOPE = #{menuScope}
  AND MENU_CODE = #{menuCode}
  AND PROD_CODE = #{prodCode}
  AND FEATURE_ID = #{featureId}
  AND TENANT_ID = #{tenantId}

mapper.insert:
INSERT INTO perm_feature_menu (
    TENANT_ID, STAT, PROD_CODE, FEATURE_ID, MENU_SCOPE, MENU_CODE, MENU_NAME, CRE_DATE, UPD_DATE
) VALUES (
    #{tenantId}, #{stat}, #{prodCode}, #{featureId}, #{menuScope}, #{menuCode}, #{menuName}, NOW(), NOW()
)

mapper.delete:
DELETE FROM perm_feature_menu
WHERE MENU_SCOPE = #{menuScope}
  AND MENU_CODE = #{menuCode}
  AND PROD_CODE = #{prodCode}
  AND FEATURE_ID = #{featureId}
  AND TENANT_ID = #{tenantId}
